    out=ROOT/'artifacts/v168_results_20261002';target=out/'validation.json';assert not target.exists();publication=read(out/'publication.json');check_bindings(publication['source_sha256']);actual=read(out/'actual_result_summary.json');check_bindings(actual['source_sha256']);before=load_catalog(ROOT,out/'previous/mcp_readonly/catalog.json',256*1024);current=load_catalog(ROOT,ROOT/'mcp_readonly/catalog.json',256*1024);old={r['id']:r for r in before['documents']};now={r['id']:r for r in current['documents']};assert len(old)==451 and len(now)==454 and all(now[k]==v for k,v in old.items())
